package ui

// AdminAuroraCSS defines the "Aurora" admin visual theme mode's chrome
// palette (teal/slate), restyling the shared, mode-agnostic sidebar/topbar/
// card/button/input markup the same way AdminNovaCSS, AdminShadcnCSS, and
// AdminWorkbenchCSS do (ADR-0041), reusing the shared semantic token names
// from AdminCSS (ADR-0053). Unlike those three, Aurora's *dashboard body* is
// not restyled here - it is its own Tailwind-authored markup (ADR-0339),
// kept in the separate, prefixed aurora.CSSText stylesheet. This file only
// covers the shell chrome, so the "aurora" family re-skins the whole shell
// the same way every other family does. See
// docs/architecture/0339-tailwind-admin-visual-family.md.
const AdminAuroraCSS = `html[data-ui-theme="aurora"]{--bg:#f8fafc;--surface:#ffffff;--surface-raised:#ffffff;--surface-hover:#f0fdfa;--bg-subtle:#f1f5f9;--ink:#0f172a;--ink-secondary:#334155;--muted:#64748b;--line:#e2e8f0;--line-light:#ccfbf1;--brand:#0f766e;--brand-hover:#0d9488;--brand-light:#0d9488;--brand-subtle:#f0fdfa;--brand-glow:rgba(13,148,136,.16);--brand-ink:#f0fdfa;--green:#16a34a;--green-subtle:#f0fdf4;--red:#dc2626;--red-subtle:#fef2f2;--amber:#d97706;--radius-xs:4px;--radius-sm:8px;--radius-md:10px;--radius-lg:14px;--radius-xl:18px;--shadow-xs:none;--shadow-sm:0 1px 2px 0 rgba(15,118,110,.06);--shadow-md:0 8px 20px rgba(15,23,42,.08);--shadow-lg:0 16px 32px rgba(15,23,42,.12);--card-highlight:0 1px 2px 0 rgba(15,118,110,.06)}html[data-ui-theme="aurora"][data-theme="dark"]{--bg:#030712;--surface:#0f172a;--surface-raised:#111827;--surface-hover:#1e293b;--bg-subtle:#0f172a;--ink:#f1f5f9;--ink-secondary:#cbd5e1;--muted:#94a3b8;--line:#1e293b;--line-light:#334155;--brand:#2dd4bf;--brand-hover:#5eead4;--brand-light:#2dd4bf;--brand-subtle:#0f2b28;--brand-glow:rgba(45,212,191,.18);--brand-ink:#042f2e;--green:#4ade80;--green-subtle:#052e16;--red:#f87171;--red-subtle:#450a0a;--amber:#fbbf24;--shadow-xs:none;--shadow-sm:0 1px 2px rgba(0,0,0,.4);--shadow-md:0 8px 22px rgba(0,0,0,.5);--shadow-lg:0 16px 32px rgba(0,0,0,.6);--card-highlight:0 1px 2px 0 rgba(0,0,0,.4)}html[data-ui-theme="aurora"] body{background:var(--bg);color:var(--ink)}html[data-ui-theme="aurora"] .studio-sidebar{background:var(--surface);border-right:1px solid var(--line);box-shadow:none}html[data-ui-theme="aurora"] .sidebar-header{border-bottom:1px solid var(--line);background:transparent}html[data-ui-theme="aurora"] .sidebar-bottom{border-top:1px solid var(--line);background:var(--bg-subtle)}html[data-ui-theme="aurora"] .studio-brand{color:var(--ink)}html[data-ui-theme="aurora"] .sidebar-section-label{color:var(--muted)}html[data-ui-theme="aurora"] .nav-item{color:var(--ink-secondary);border-radius:var(--radius-sm)}html[data-ui-theme="aurora"] .brand-text small{color:var(--muted)}html[data-ui-theme="aurora"] .brand-logo-mark{background:var(--brand);color:var(--brand-ink);border-radius:var(--radius-md);box-shadow:none}html[data-ui-theme="aurora"] .nav-item:hover{background:var(--brand-subtle);color:var(--brand-light);border-color:transparent}html[data-ui-theme="aurora"] .nav-item.is-active{background:var(--brand-subtle)!important;color:var(--brand-light)!important;border-color:transparent!important;box-shadow:none!important;font-weight:600!important}html[data-ui-theme="aurora"] .studio-topbar{background:var(--surface);border-bottom:1px solid var(--line);box-shadow:none}html[data-ui-theme="aurora"] .studio-card,html[data-ui-theme="aurora"] .dashboard-kpi,html[data-ui-theme="aurora"] .dashboard-card,html[data-ui-theme="aurora"] .collection-tile,html[data-ui-theme="aurora"] .tool-tile,html[data-ui-theme="aurora"] .meta-item,html[data-ui-theme="aurora"] .report-info-card{background:var(--surface);border-color:var(--line);box-shadow:var(--card-highlight)}html[data-ui-theme="aurora"] .studio-card,html[data-ui-theme="aurora"] .dashboard-kpi,html[data-ui-theme="aurora"] .dashboard-card,html[data-ui-theme="aurora"] .report-info-card{border-radius:var(--radius-lg)}html[data-ui-theme="aurora"] .studio-form button:not(.button-quiet):not(.button-secondary),html[data-ui-theme="aurora"] .button:not(.button-quiet):not(.button-secondary),html[data-ui-theme="aurora"] .studio-card button:not(.button-quiet):not(.button-secondary){border-radius:var(--radius-md);background:var(--brand);color:var(--brand-ink);box-shadow:none}html[data-ui-theme="aurora"] .studio-form button:not(.button-quiet):not(.button-secondary):hover,html[data-ui-theme="aurora"] .button:not(.button-quiet):not(.button-secondary):hover,html[data-ui-theme="aurora"] .studio-card button:not(.button-quiet):not(.button-secondary):hover{background:var(--brand-hover);color:var(--brand-ink);transform:none;box-shadow:none}html[data-ui-theme="aurora"] .button-quiet,html[data-ui-theme="aurora"] .button-secondary{border-radius:var(--radius-md);background:var(--bg-subtle)!important;color:var(--ink)!important;border:1px solid var(--line)!important;box-shadow:none}html[data-ui-theme="aurora"] .button-quiet:hover,html[data-ui-theme="aurora"] .button-secondary:hover{background:var(--surface-hover)!important;color:var(--brand-light)!important;border-color:var(--line-light)!important}html[data-ui-theme="aurora"] .studio-search{border-color:var(--line);border-radius:var(--radius-md);background:var(--bg-subtle);box-shadow:none}html[data-ui-theme="aurora"] .studio-search:hover{border-color:var(--line-light);background:var(--surface)}html[data-ui-theme="aurora"] .studio-search:focus-within{border-color:var(--brand);background:var(--surface);box-shadow:0 0 0 1px var(--brand)}html[data-ui-theme="aurora"] .theme-toggle-btn,html[data-ui-theme="aurora"] .studio-user{border-color:var(--line);border-radius:var(--radius-md);background:var(--surface);box-shadow:none}html[data-ui-theme="aurora"] input,html[data-ui-theme="aurora"] select,html[data-ui-theme="aurora"] textarea,html[data-ui-theme="aurora"] .studio-form input,html[data-ui-theme="aurora"] .studio-form select,html[data-ui-theme="aurora"] .studio-form textarea,html[data-ui-theme="aurora"] .studio-card input,html[data-ui-theme="aurora"] .studio-card select,html[data-ui-theme="aurora"] .studio-card textarea{border-radius:var(--radius-md);background:var(--surface);border-color:var(--line);color:var(--ink)}html[data-ui-theme="aurora"] input:focus,html[data-ui-theme="aurora"] select:focus,html[data-ui-theme="aurora"] textarea:focus,html[data-ui-theme="aurora"] .studio-form input:focus,html[data-ui-theme="aurora"] .studio-form select:focus,html[data-ui-theme="aurora"] .studio-form textarea:focus,html[data-ui-theme="aurora"] .studio-card input:focus,html[data-ui-theme="aurora"] .studio-card select:focus,html[data-ui-theme="aurora"] .studio-card textarea:focus{border-color:var(--brand);box-shadow:0 0 0 2px var(--brand-glow)}html[data-ui-theme="aurora"] .studio-heading h1,html[data-ui-theme="aurora"] .dashboard-welcome h2{letter-spacing:-.03em}html[data-ui-theme="aurora"] .studio-badge-status{border-color:var(--line);background:var(--bg-subtle);color:var(--ink-secondary);border-radius:999px}html[data-ui-theme="aurora"] ::selection{background:var(--brand);color:var(--brand-ink)}html[data-ui-theme="aurora"] :focus-visible{outline:2px solid var(--brand);outline-offset:2px}`

// AdminAuroraDensityCSS mirrors AdminNovaDensityCSS's layout density rules,
// re-scoped to the Aurora mode's chrome.
const AdminAuroraDensityCSS = `html[data-ui-theme="aurora"] .studio-content{max-width:1600px}html[data-ui-theme="aurora"] .studio-card,html[data-ui-theme="aurora"] .dashboard-card{padding:20px 22px}html[data-ui-theme="aurora"] .studio-card h2,html[data-ui-theme="aurora"] .dashboard-card h2{font-size:1.02rem;letter-spacing:-.01em}html[data-ui-theme="aurora"] .studio-card th{background:var(--bg-subtle);color:var(--muted);font-size:.68rem;letter-spacing:.06em;text-transform:uppercase}html[data-ui-theme="aurora"] .studio-card td{font-size:.8rem}html[data-ui-theme="aurora"] .nav-item{min-height:38px;padding:9px 12px;font-size:.84rem;border-radius:var(--radius-md)}html[data-ui-theme="aurora"] .sidebar-section-label{margin:12px 10px 4px;font-size:.64rem;letter-spacing:.08em}html[data-ui-theme="aurora"] .studio-search{min-height:36px;height:36px;font-size:.84rem;border-radius:var(--radius-md)}html[data-ui-theme="aurora"] .button,html[data-ui-theme="aurora"] .studio-form button{min-height:38px;height:38px;padding:0 18px;font-size:.82rem;font-weight:600;border-radius:var(--radius-md)}html[data-ui-theme="aurora"] .button-quiet,html[data-ui-theme="aurora"] .button-secondary{min-height:38px;height:38px;padding:0 18px;font-size:.82rem;border-radius:var(--radius-md);color:var(--ink)!important}html[data-ui-theme="aurora"] .studio-alert{border:1px solid var(--red);border-radius:var(--radius-md)}html[data-ui-theme="aurora"] .studio-form label{font-size:.76rem;font-weight:600}html[data-ui-theme="aurora"] .studio-form input,html[data-ui-theme="aurora"] .studio-form select,html[data-ui-theme="aurora"] .studio-form textarea{font-size:.82rem;border-radius:var(--radius-md)}`

// AdminAuroraTypeCSS mirrors AdminNovaTypeCSS's font-family rules, re-scoped
// to the Aurora mode's chrome (the Tailwind-authored dashboard body sets its
// own font stack via utility classes, independent of this).
const AdminAuroraTypeCSS = `html[data-ui-theme="aurora"] body,html[data-ui-theme="aurora"] button,html[data-ui-theme="aurora"] input,html[data-ui-theme="aurora"] select,html[data-ui-theme="aurora"] textarea{font-family:"Inter",-apple-system,BlinkMacSystemFont,"Segoe UI Variable","Segoe UI",sans-serif!important;letter-spacing:-.011em}html[data-ui-theme="aurora"] code,html[data-ui-theme="aurora"] kbd,html[data-ui-theme="aurora"] pre{font-family:"JetBrains Mono","IBM Plex Mono","SFMono-Regular",Consolas,monospace!important}`

// AdminAuroraDashboardLayoutCSS toggles which dashboard markup is visible for
// the fifth admin visual family, "aurora" (ADR-0339), following the exact
// client-only display-toggle pattern AdminNovaDashboardLayoutCSS established
// for Nova (ADR-0335): every family's dashboard markup is always rendered
// into the page, and CSS alone decides which one is visible for the active
// html[data-ui-theme] value. Unlike the other four families, Aurora's own
// dashboard body is NOT re-skinned by AdminAuroraCSS above - it is authored
// directly with Tailwind utility classes and its own compiled, namespaced
// stylesheet (aurora.CSSText, concatenated into the shared admin stylesheet
// in admin_shell.go). See docs/architecture/0339-tailwind-admin-visual-family.md.
const AdminAuroraDashboardLayoutCSS = `html:not([data-ui-theme="aurora"]) .aurora-dashboard{display:none}
html[data-ui-theme="aurora"] .wb-dashboard{display:none}
html[data-ui-theme="aurora"] .nova-dashboard{display:none}`
